// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Layout } from '@stdlib/types/blas';

/**
* Norm parameter.
*
* ## Notes
*
* The norm parameter can be one of the following:
*
* -   'max': finds the maximum absolute value
* -   'infinity': finds the infinity norm
* -   'one': finds the one norm
* -   'frobenius': finds the frobenius norm
*/
type Norm = 'max' | 'one' | 'infinity' | 'frobenius';

/**
* Interface describing `dlange`.
*/
interface Routine {
	/**
	* Returns the value of the one norm, or the frobenius norm, or the infinity norm, or the element with the largest absolute value of a real matrix `A`.
	*
	* ## Notes
	*
	* -   use `norm` = `max`, to calculate the element with the largest absolute value
	* -   use `norm` = `one`, to calculate the one norm
	* -   use `norm` = `infinity`, to calculate the infinity norm
	* -   use `norm` = `frobenius`, to calculate the frobenius norm
	*
	* @param order - storage layout
	* @param norm - specifies the type of norm to be calculated
	* @param M - number of rows in `A`
	* @param N - number of columns in `A`
	* @param A - input array
	* @param LDA - stride of the first dimension of `A` (a.k.a., leading dimension of the matrix `A`)
	* @param work - only used to compute the infinity norm, should have `M` indexed elements if computing the infinity norm otherwise it's fine to pass a dummy array
	* @returns required norm value
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var A = new Float64Array( [ 1.0, 4.0, 7.0, 10.0, 2.0, 5.0, 8.0, 11.0, 3.0, 6.0, 9.0, 12.0 ] );
	* var work = new Float64Array( 3 );
	*
	* var out = dlange( 'row-major', 'frobenius', 3, 4, A, 4, work );
	* // returns ~25.5
	*/
	( order: Layout, norm: Norm, M: number, N: number, A: Float64Array, LDA: number, work: Float64Array ): number;

	/**
	* Returns the value of the one norm, or the frobenius norm, or the infinity norm, or the element with the largest absolute value of a real matrix `A`.
	*
	* ## Notes
	*
	* -   use `norm` = `max`, to calculate the element with the largest absolute value
	* -   use `norm` = `one`, to calculate the one norm
	* -   use `norm` = `infinity`, to calculate the infinity norm
	* -   use `norm` = `frobenius`, to calculate the frobenius norm
	*
	* @param norm - specifies the type of norm to be calculated
	* @param M - number of rows in `A`
	* @param N - number of columns in `A`
	* @param A - input array
	* @param strideA1 - stride of the first dimension of `A`
	* @param strideA2 - stride of the second dimension of `A`
	* @param offsetA - starting index of `A`
	* @param work - only used to compute the infinity norm, should have `M` indexed elements if computing the infinity norm otherwise it's fine to pass a dummy array
	* @param strideWork - stride length of `work`
	* @param offsetWork - starting index of `work`
	* @returns required norm value
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var A = new Float64Array( [ 1.0, 4.0, 7.0, 10.0, 2.0, 5.0, 8.0, 11.0, 3.0, 6.0, 9.0, 12.0 ] );
	* var work = new Float64Array( 3 );
	*
	* var out = dlange.ndarray( 'frobenius', 3, 4, A, 4, 1, 0, work, 1, 0 );
	* // returns ~25.5
	*/
	ndarray( norm: Norm, M: number, N: number, A: Float64Array, strideA1: number, strideA2: number, offsetA: number, work: Float64Array, strideWork: number, offsetWork: number ): number;
}

/**
* Returns the value of the one norm, or the frobenius norm, or the infinity norm, or the element with the largest absolute value of a real matrix `A`.
*
* ## Notes
*
* -   use `norm` = `max`, to calculate the element with the largest absolute value
* -   use `norm` = `one`, to calculate the one norm
* -   use `norm` = `infinity`, to calculate the infinity norm
* -   use `norm` = `frobenius`, to calculate the frobenius norm
*
* @param order - storage layout
* @param norm - specifies the type of norm to be calculated
* @param M - number of rows in `A`
* @param N - number of columns in `A`
* @param A - input array
* @param LDA - stride of the first dimension of `A` (a.k.a., leading dimension of the matrix `A`)
* @param work - only used to compute the infinity norm, should have `M` indexed elements if computing the infinity norm otherwise it's fine to pass a dummy array
* @returns required norm value
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var A = new Float64Array( [ 1.0, 4.0, 7.0, 10.0, 2.0, 5.0, 8.0, 11.0, 3.0, 6.0, 9.0, 12.0 ] );
* var work = new Float64Array( 3 );
*
* var out = dlange( 'row-major', 'frobenius', 3, 4, A, 4, work );
* // returns ~25.5
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var A = new Float64Array( [ 1.0, 4.0, 7.0, 10.0, 2.0, 5.0, 8.0, 11.0, 3.0, 6.0, 9.0, 12.0 ] );
* var work = new Float64Array( 3 );
*
* var out = dlange.ndarray( 'frobenius', 3, 4, A, 4, 1, 0, work, 1, 0 );
* // returns ~25.5
*/
declare var dlange: Routine;


// EXPORTS //

export = dlange;
